-- =====================================================================
-- Phase 34 - Import: French Tech funding deals, 2020 (bulk backfill)
-- Source spreadsheet: ft-funding-2020.xlsx (742 deal rows, 718 unique
-- companies). Idempotent: re-running attaches nothing new.
--
-- Strategy
--   * Load the sheet into a transient staging table (stg_ft_2020).
--   * Create only genuinely-new organizations (no slug match AND no
--     existing SIREN); existing orgs are reused.
--   * Resolve each sheet row to an org via SIREN first, then slug.
--   * Insert funding rounds (deduped on org + date + stage), investor
--     links (matched to existing investor orgs by slug), sector links,
--     a primary-sector promotion, and legal entities (SIRENs not yet
--     present anywhere).
--   * Drop the staging tables.
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- DDL: staging table
-- ---------------------------------------------------------------------
-- staging table for the FT 2020 bulk import (dropped at the end)
CREATE EXTENSION IF NOT EXISTS "unaccent";
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS secondary_city_id UUID REFERENCES cities(id) ON DELETE SET NULL;
DROP TABLE IF EXISTS stg_ft_2020;
CREATE TABLE stg_ft_2020 (
  org_name TEXT, slug TEXT, city TEXT, stage TEXT, amount_eur NUMERIC, amount_original NUMERIC,
  currency TEXT, announced_date DATE, website TEXT, investors TEXT, sectors TEXT, siren TEXT);

