: "HealthTech||BioTech", "siren": "509059879"}, {"org_name": "Haudecoeur", "slug": "haudecoeur", "city": "La Courneuve", "stage": "undisclosed", "amount_eur": null, "amount_original": null, "currency": null, "announced_date": "2020-09-01", "website": "https://www.haudecoeur.fr/", "investors": "Eurazeo", "sectors": "E-commerce & Retail||FoodTech", "siren": "662006402"}, {"org_name": "MediaSchool Group", "slug": "mediaschool-group", "city": "Paris", "stage": "undisclosed", "amount_eur": null, "amount_original": null, "currency": null, "announced_date": "2020-05-01", "website": "http://www.mediaschool.eu", "investors": "", "sectors": "EdTech||Telecom", "siren": "490885498"}, {"org_name": "WORMSENSING", "slug": "wormsensing", "city": "Grenoble", "stage": "undisclosed", "amount_eur": null, "amount_original": null, "currency": null, "announced_date": "2020-01-08", "website": "https://www.wormsensing.com/", "investors": "CEA Investissement", "sectors": "Semiconductors||DeepTech||SpaceTech & Aerospace||Robotics||Mobility||CleanTech||Energy", "siren": "880418033"}]$j$) AS (org_name TEXT, slug TEXT, city TEXT, stage TEXT, amount_eur NUMERIC, amount_original NUMERIC, currency TEXT, announced_date TEXT, website TEXT, investors TEXT, sectors TEXT, siren TEXT);
-- ---------------------------------------------------------------------
-- Resolution: orgs, cities, rounds, investors, sectors, legal entities
-- ---------------------------------------------------------------------

-- Step A: create orgs that are genuinely new (no slug match AND no existing SIREN)
INSERT INTO organizations (id,name,slug,organization_type,website,status,country,legacy_source,created_at,updated_at)
SELECT uuid_generate_v4(), d.org_name, d.slug, 'startup'::organization_type, NULLIF(d.website,''), 'active'::organization_status,'France','ft_funding_2020',NOW(),NOW()
FROM (SELECT DISTINCT ON (slug) slug, org_name, website, siren FROM stg_ft_2020 ORDER BY slug, siren NULLS LAST) d
WHERE NOT EXISTS (SELECT 1 FROM organizations o WHERE o.slug=d.slug)
  AND NOT EXISTS (SELECT 1 FROM legal_entities le WHERE d.siren IS NOT NULL AND le.siren=d.siren)
ON CONFLICT (slug) DO NOTHING;

-- Step B: resolver mapping each sheet slug -> the org it belongs to.
-- DISTINCT ON guards against a SIREN matching multiple legal_entities rows
-- (legal_entities has no unique constraint on siren); prefer the SIREN-matched org.
DROP TABLE IF EXISTS _r2020;
CREATE TABLE _r2020 AS
SELECT DISTINCT ON (d.slug) d.slug, COALESCE(le.organization_id, o.id) AS org_id
FROM (SELECT slug, (array_agg(siren) FILTER (WHERE siren IS NOT NULL))[1] AS siren FROM stg_ft_2020 GROUP BY slug) d
LEFT JOIN legal_entities le ON le.siren=d.siren
LEFT JOIN organizations o ON o.slug=d.slug
ORDER BY d.slug, (le.organization_id IS NOT NULL) DESC, le.organization_id, o.id;
CREATE UNIQUE INDEX _r2020_slug ON _r2020(slug);

-- Step C: cities (new ones only), then link (COALESCE keeps existing)
INSERT INTO cities (id,name,slug,country,created_at,updated_at)
SELECT uuid_generate_v4(), c.city, lower(regexp_replace(regexp_replace(unaccent(c.city), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g')), 'France', NOW(),NOW()
FROM (SELECT DISTINCT city FROM stg_ft_2020 WHERE city IS NOT NULL AND city<>'') c
ON CONFLICT (slug) DO NOTHING;

UPDATE organizations o SET city_id=ci.id, updated_at=NOW()
FROM _r2020 r
JOIN stg_ft_2020 s ON s.slug=r.slug
JOIN cities ci ON ci.slug=lower(regexp_replace(regexp_replace(unaccent(s.city), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE o.id=r.org_id AND o.city_id IS NULL AND s.city IS NOT NULL AND s.city<>'';

-- Step D: funding rounds (dedup on org+date+stage)
INSERT INTO funding_rounds (id, organization_id, stage, amount_eur, currency_original, amount_original, announced_date, is_estimated, is_verified, source_name, created_at)
SELECT uuid_generate_v4(), r.org_id, s.stage::funding_stage, s.amount_eur, s.currency, s.amount_original, s.announced_date, FALSE, FALSE, 'ft_funding_2020', NOW()
FROM stg_ft_2020 s JOIN _r2020 r ON r.slug=s.slug
WHERE NOT EXISTS (SELECT 1 FROM funding_rounds fr WHERE fr.organization_id=r.org_id AND fr.announced_date=s.announced_date AND fr.stage=s.stage::funding_stage);

-- Step E: investor links (split on '||'); dedup per round+investor
INSERT INTO funding_round_investors (id, funding_round_id, investor_id, is_lead, investor_name, created_at)
SELECT DISTINCT uuid_generate_v4(), fr.id, inv.id, FALSE, iv.name, NOW()
FROM stg_ft_2020 s
JOIN _r2020 r ON r.slug=s.slug
JOIN funding_rounds fr ON fr.organization_id=r.org_id AND fr.announced_date=s.announced_date AND fr.stage=s.stage::funding_stage AND fr.source_name='ft_funding_2020'
CROSS JOIN LATERAL unnest(string_to_array(s.investors,'||')) AS iv(name)
JOIN organizations inv ON inv.slug=lower(regexp_replace(regexp_replace(unaccent(iv.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE iv.name<>'' AND NOT EXISTS (SELECT 1 FROM funding_round_investors x WHERE x.funding_round_id=fr.id AND x.investor_id=inv.id);

-- Step F: sector links (split on '||'); is_primary FALSE
INSERT INTO organization_sectors (id, organization_id, sector_id, is_primary, created_at)
SELECT DISTINCT uuid_generate_v4(), r.org_id, sec.id, FALSE, NOW()
FROM stg_ft_2020 s
JOIN _r2020 r ON r.slug=s.slug
CROSS JOIN LATERAL unnest(string_to_array(s.sectors,'||')) AS sc(name)
JOIN sectors sec ON sec.slug=lower(regexp_replace(regexp_replace(unaccent(sc.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE sc.name<>''
ON CONFLICT (organization_id, sector_id) DO NOTHING;

-- Step G: promote a primary sector (first listed) where the org has none
UPDATE organization_sectors os SET is_primary=TRUE
FROM (
  SELECT DISTINCT ON (r.org_id) r.org_id, sec.id AS sector_id
  FROM stg_ft_2020 s JOIN _r2020 r ON r.slug=s.slug
  CROSS JOIN LATERAL unnest(string_to_array(s.sectors,'||')) WITH ORDINALITY AS sc(name,ord)
  JOIN sectors sec ON sec.slug=lower(regexp_replace(regexp_replace(unaccent(sc.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
  WHERE sc.name<>''
  ORDER BY r.org_id, sc.ord
) first
WHERE os.organization_id=first.org_id AND os.sector_id=first.sector_id
  AND NOT EXISTS (SELECT 1 FROM organization_sectors x WHERE x.organization_id=first.org_id AND x.is_primary=TRUE);

-- Step H: legal entities (only SIRENs not already present anywhere)
INSERT INTO legal_entities (id, organization_id, legal_name, siren, country, is_primary, created_at, updated_at)
SELECT DISTINCT ON (s.siren) uuid_generate_v4(), r.org_id, upper(s.org_name), s.siren, 'France',
  NOT EXISTS (SELECT 1 FROM legal_entities le2 WHERE le2.organization_id=r.org_id), NOW(),NOW()
FROM stg_ft_2020 s JOIN _r2020 r ON r.slug=s.slug
WHERE s.siren IS NOT NULL AND s.siren<>''
  AND NOT EXISTS (SELECT 1 FROM legal_entities le WHERE le.siren=s.siren)
ORDER BY s.siren;

-- ---------------------------------------------------------------------
-- Verification (counts for this import)
-- ---------------------------------------------------------------------

SELECT 'Rounds (2020)' AS entity, COUNT(*)::text FROM funding_rounds WHERE source_name='ft_funding_2020'
UNION ALL SELECT 'New startups', COUNT(*)::text FROM organizations WHERE legacy_source='ft_funding_2020' AND organization_type='startup'
UNION ALL SELECT 'New investor orgs', COUNT(*)::text FROM organizations WHERE legacy_source='ft_funding_2020' AND organization_type='investor'
UNION ALL SELECT 'Investor links (2020)', COUNT(*)::text FROM funding_round_investors fri JOIN funding_rounds fr ON fr.id=fri.funding_round_id WHERE fr.source_name='ft_funding_2020'
UNION ALL SELECT 'Legal entities added', COUNT(*)::text FROM legal_entities WHERE created_at > NOW() - INTERVAL '1 hour' AND country='France';

-- ---------------------------------------------------------------------
-- Cleanup: drop staging tables
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS _r2020;
DROP TABLE IF EXISTS stg_ft_2020;

COMMIT;
